const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const STORE={food:'scirocco_admin_food_v1',wine:'scirocco_admin_wines_v1',drinks:'scirocco_admin_drinks_v1',tags:'scirocco_admin_tags_v1',wineLib:'scirocco_admin_wine_library_v2',contentLanguages:'scirocco_admin_content_languages_v1'};
const LANGUAGE_CATALOG={it:'Italiano',en:'English',es:'Español',fr:'Français',de:'Deutsch',pt:'Português'};
function contentLanguages(){try{const v=JSON.parse(localStorage.getItem(STORE.contentLanguages));const clean=Array.isArray(v)?v.filter(l=>typeof l==='string'&&l.trim()&&LANGUAGE_CATALOG[l]):[];return clean.length?[...new Set(clean)]:['it','en','es']}catch{return ['it','en','es']}}
function saveContentLanguages(v){const clean=(Array.isArray(v)?v:[]).filter(l=>typeof l==='string'&&l.trim()&&LANGUAGE_CATALOG[l]);localStorage.setItem(STORE.contentLanguages,JSON.stringify([...new Set(clean.length?clean:['it','en','es'])]))}
const SOURCE={food:new URL('menu/data/menu.json',document.baseURI).href,wine:new URL('menu/data/wines.json',document.baseURI).href,drinks:new URL('menu/data/drinks.json',document.baseURI).href,catalog:new URL('menu/data/wine-catalog.json',document.baseURI).href};
let kind='food',datasets={},selectedId=null,pendingDelete=null,dragId=null,newDraft=null;document.body.dataset.kind=kind;
const activeCategory={food:'all',wine:'all',drinks:'all'}; let activeWineCountry='all';
const DRINK_CATEGORIES=[{id:'bevande',label:'BEVANDE'},{id:'caffetteria',label:'CAFFETTERIA'},{id:'birre',label:'BIRRE'},{id:'amari',label:'AMARI'},{id:'distillati',label:'DISTILLATI'}];
const WINE_CATEGORIES=[{id:'sparkling',label:'BOLLICINE'},{id:'white',label:'BIANCHI'},{id:'red',label:'ROSSI'},{id:'rose',label:'ROSATI'}];
const WINE_COUNTRIES=[{id:'all',label:'TUTTI'},{id:'italy',label:'ITALIA'},{id:'france',label:'FRANCIA'},{id:'spain',label:'SPAGNA'},{id:'rest',label:'RESTO DEL MONDO'}];
const WINE_STYLE_DEFAULTS=[
 {id:'fresh',label:'Fresco',descriptors:['Vivo','Agile','Immediato']},
 {id:'mineral',label:'Minerale',descriptors:['Teso','Sapido','Verticale']},
 {id:'elegant',label:'Elegante',descriptors:['Fine','Equilibrato','Persistente']},
 {id:'structured',label:'Strutturato',descriptors:['Intenso','Complesso','Profondo']},
 {id:'aromatic',label:'Aromatico',descriptors:['Espressivo','Fragrante','Avvolgente']},
 {id:'soft',label:'Morbido',descriptors:['Rotondo','Armonioso','Vellutato']}
];
const WINE_LIBRARY_DEFAULT={
 countries:[{id:'italy',label:'Italia'},{id:'france',label:'Francia'},{id:'spain',label:'Spagna'}],
 regions:{italy:['Piemonte','Toscana','Puglia','Alto Adige','Friuli-Venezia Giulia','Veneto','Campania','Sicilia','Abruzzo'],france:['Bordeaux','Borgogna','Rhône','Loira','Alsazia','Provence'],spain:['Rioja','Ribera del Duero','Priorat','Galizia','Catalogna','Castilla y León','Navarra']},
 denominations:{
  'italy|sparkling':['Trentodoc','Franciacorta','Alta Langa','Oltrepò Pavese','Prosecco'],
  'france|sparkling':['Champagne','Crémant'],'spain|sparkling':['Cava','Corpinnat']
 },producers:{},
 grapes:{white:['Chardonnay','Glera','Macabeo','Xarel·lo','Parellada','Sauvignon Blanc','Riesling','Pinot Bianco','Vermentino','Fiano','Verdeca','Albariño'],red:['Pinot Nero','Pinot Meunier','Nebbiolo','Sangiovese','Negroamaro','Primitivo','Grenache','Garnacha','Syrah','Cabernet Sauvignon','Merlot','Cinsault']},
 styles:WINE_STYLE_DEFAULTS
};
function normalizeWineStyles(l){
 if(!Array.isArray(l.styles)||!l.styles.length||typeof l.styles[0]==='string')l.styles=JSON.parse(JSON.stringify(WINE_STYLE_DEFAULTS));
 l.styles=l.styles.map(st=>({id:st.id||slug(st.label||st),label:st.label||String(st),descriptors:Array.isArray(st.descriptors)&&st.descriptors.length===3?st.descriptors:['Descrittore 1','Descrittore 2','Descrittore 3']}));
 return l;
}
function wineLib(){try{return normalizeWineStyles(JSON.parse(localStorage.getItem(STORE.wineLib))||structuredClone(WINE_LIBRARY_DEFAULT))}catch{return JSON.parse(JSON.stringify(WINE_LIBRARY_DEFAULT))}}
function saveWineLib(v){localStorage.setItem(STORE.wineLib,JSON.stringify(normalizeWineStyles(v)))}
function ensureWineLib(){
 if(!localStorage.getItem(STORE.wineLib))saveWineLib(JSON.parse(JSON.stringify(WINE_LIBRARY_DEFAULT)));
 const l=wineLib();
 (datasets.wine?.wines||[]).forEach(w=>{
  if(w.region&&w.type!=='sparkling'){const a=l.regions[w.country]||(l.regions[w.country]=[]);if(!a.includes(w.region))a.push(w.region)}
  if(w.denomination){const key=denomKey(w.country,w.type,w.region);const a=l.denominations[key]||(l.denominations[key]=[]);if(!a.includes(w.denomination))a.push(w.denomination)}
  if(w.producer&&w.denomination){const key=producerKey(w.country,w.type,w.region,w.denomination);const a=l.producers[key]||(l.producers[key]=[]);if(!a.includes(w.producer))a.push(w.producer)}
  ;(w.grapes||[]).forEach(g=>{if(!l.grapes.white.includes(g)&&!l.grapes.red.includes(g))l.grapes.white.push(g)})
 });
 saveWineLib(l)
}
function denomKey(country,type,region=''){return type==='sparkling'?`${country}|sparkling`:`${country}|${type}|${region}`}
function producerKey(country,type,region,denom){return `${denomKey(country,type,region)}|${denom}`}
function opts(values,current,addLabel='＋ Aggiungi…'){const a=[...new Set((values||[]).filter(Boolean))];if(current&&!a.includes(current))a.unshift(current);return a.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')+`<option value="__add__">${addLabel}</option>`}
function libSelect(name,label,values,current,addKind){return `<div class="field"><label>${label}</label><select name="${name}" class="wine-lib-select" data-add-kind="${addKind}">${opts(values,current)}</select></div>`}
function selectorSummary(values,empty='NESSUNA SELEZIONE'){return values.length?values.map(v=>`<span class="selector-chip">${esc(v)}</span>`).join(''):`<span class="selector-empty">${empty}</span>`}
function openMultiSelector({title,options,selected,onApply}){const chosen=new Set(selected||[]),wrap=document.createElement('div');wrap.className='modal-backdrop dynamic-modal';const draw=()=>{wrap.querySelector('.choice-sheet-options').innerHTML=options.map(o=>`<button type="button" class="choice-sheet-option ${chosen.has(o.value)?'is-selected':''}" data-value="${esc(o.value)}"><span>${esc(o.label)}</span><b>${chosen.has(o.value)?'✓':''}</b></button>`).join('');wrap.querySelectorAll('.choice-sheet-option').forEach(b=>b.onclick=()=>{chosen.has(b.dataset.value)?chosen.delete(b.dataset.value):chosen.add(b.dataset.value);draw()})};wrap.innerHTML=`<div class="confirm-box choice-sheet"><p class="eyebrow">SELEZIONE</p><h2>${esc(title)}</h2><div class="choice-sheet-options"></div><div class="confirm-actions"><button type="button" class="btn ghost" data-close>ANNULLA</button><button type="button" class="btn primary" data-apply>CONFERMA</button></div></div>`;document.body.appendChild(wrap);draw();wrap.querySelector('[data-close]').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};wrap.querySelector('[data-apply]').onclick=()=>{onApply([...chosen]);wrap.remove()}}
function hiddenChecks(name,options,selected,extra=''){return `<div class="selector-hidden-inputs">${options.map(o=>`<input type="checkbox" name="${name}" value="${esc(o.value)}" ${extra} ${selected.includes(o.value)?'checked':''}>`).join('')}</div>`}
function wineStylesField(x){const styles=wineLib().styles||[],selected=(x.style||[]).map(styleId),opts=styles.map(st=>({value:st.id,label:st.label}));return `<section class="form-section"><div class="section-title-row"><h3 class="form-section-title">STILE</h3><button type="button" class="text-action" id="manageWineStyles">＋ GESTISCI STILI</button></div><button type="button" class="field-selector" id="wineStyleSelector"><span>SELEZIONA STILI</span><b>⌄</b></button><div class="selector-summary" id="wineStyleSummary">${selectorSummary(styles.filter(st=>selected.includes(st.id)).map(st=>st.label))}</div>${hiddenChecks('wineStyle',opts,selected)}</section>`}
function grapesField(x){const l=wineLib(),selected=x.grapes||[];return `<section class="form-section grape-section"><div class="section-title-row"><h3 class="form-section-title">VITIGNI</h3><button type="button" class="text-action" id="addGrape">＋ AGGIUNGI VITIGNO</button></div><div class="grape-selector-grid">${['white','red'].map(t=>{const label=t==='white'?'UVA BIANCA':'UVA ROSSA',values=l.grapes[t],chosen=selected.filter(g=>values.includes(g)),opts=values.map(g=>({value:g,label:g}));return `<div class="grape-selector-card"><button type="button" class="field-selector grape-selector-trigger" data-grape-selector="${t}"><span>${label}</span><b>⌄</b></button><div class="selector-summary" data-grape-summary="${t}">${selectorSummary(chosen,'NESSUN VITIGNO')}</div>${hiddenChecks('wineGrape',opts,chosen,`data-grape-type="${t}"`)}</div>`}).join('')}</div></section>`}
function wireGrapeTypes(){document.querySelectorAll('[data-grape-selector]').forEach(btn=>btn.onclick=()=>{const type=btn.dataset.grapeSelector,label=type==='white'?'UVA BIANCA':'UVA ROSSA',l=wineLib(),inputs=[...document.querySelectorAll(`input[name="wineGrape"][data-grape-type="${type}"]`)];openMultiSelector({title:label,options:l.grapes[type].map(g=>({value:g,label:g})),selected:inputs.filter(i=>i.checked).map(i=>i.value),onApply:values=>{inputs.forEach(i=>i.checked=values.includes(i.value));const host=document.querySelector(`[data-grape-summary="${type}"]`);if(host)host.innerHTML=selectorSummary(values,'NESSUN VITIGNO')}})})}
function wireWineStyleSelector(){const btn=$('#wineStyleSelector');if(!btn)return;const styles=wineLib().styles||[],inputs=[...document.querySelectorAll('input[name="wineStyle"]')];btn.onclick=()=>openMultiSelector({title:'STILE DEL VINO',options:styles.map(st=>({value:st.id,label:st.label})),selected:inputs.filter(i=>i.checked).map(i=>i.value),onApply:values=>{inputs.forEach(i=>i.checked=values.includes(i.value));const labels=styles.filter(st=>values.includes(st.id)).map(st=>st.label);$('#wineStyleSummary').innerHTML=selectorSummary(labels)}})}
function agingField(x){let steps=x.agingSteps;if(!Array.isArray(steps)||!steps.length){const m=String(x.aging||'').match(/(\d+)\s*(mesi|anni)/i);steps=m?[{vessel:x.type==='sparkling'?'Lieviti':'Bottiglia',duration:m[1],unit:m[2].toLowerCase()}]:[]}return `<section class="form-section"><h3 class="form-section-title">AFFINAMENTO</h3><div class="aging-builder"><div class="aging-rows">${steps.map(agingRow).join('')}</div><button type="button" class="text-action add-aging">＋ AGGIUNGI AFFINAMENTO</button><p class="aging-help">Aggiungi uno o più passaggi di affinamento. Es. sui lieviti per 72 mesi.</p></div></section>`}
function agingRow(a={}){const vessels=['Lieviti','Acciaio','Cemento','Anfora','Barrique','Tonneau','Botte grande','Bottiglia','Altro'];return `<div class="aging-row"><div class="field"><label>CONTENITORE</label><select name="agingVessel">${vessels.map(v=>`<option ${v===a.vessel?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>DURATA</label><input name="agingDuration" type="number" min="0" step="1" value="${esc(a.duration||'')}" placeholder="Es. 36"></div><div class="field"><label>UNITÀ</label><select name="agingUnit"><option value="mesi" ${a.unit!=='anni'?'selected':''}>MESI</option><option value="anni" ${a.unit==='anni'?'selected':''}>ANNI</option></select></div><button type="button" class="remove-aging" aria-label="Rimuovi affinamento">×</button></div>`}
function vintageField(x){if(x.type==='sparkling'){const isVintage=x.vintage&&x.vintage!=='NV'&&x.vintage!=='S.A.';return `<div class="field"><label>ANNATA</label><select name="vintageMode"><option value="non-vintage" ${!isVintage?'selected':''}>Non millesimato</option><option value="vintage" ${isVintage?'selected':''}>Millesimato</option></select></div><div class="field vintage-year" ${isVintage?'':'hidden'}><label>ANNO</label><input name="vintageYear" type="number" min="1900" max="2100" value="${isVintage?esc(x.vintage):''}"></div>`}return `<div class="field"><label>ANNATA</label><input name="vintageYear" type="number" min="1900" max="2100" value="${/^\\d{4}$/.test(String(x.vintage||''))?esc(x.vintage):''}" placeholder="es. 2021"></div><div class="field"><label>SENZA ANNATA</label><label class="switch-field"><input type="checkbox" name="noVintage" ${!/^\\d{4}$/.test(String(x.vintage||''))?'checked':''}><span></span><b>${!/^\\d{4}$/.test(String(x.vintage||''))?'SÌ':'NO'}</b></label></div>`}
function dosageField(x){if(x.type!=='sparkling')return '';const cats=['Brut Nature','Pas Dosé','Dosaggio Zero','Extra Brut','Brut','Extra Dry','Dry / Sec','Demi-Sec','Dolce / Doux'];const current=String(x.dosageCategory||x.dosage||'');return `<div class="field"><label>DOSAGGIO</label><select name="dosageCategory">${cats.map(c=>`<option value="${esc(c)}" ${current.toLowerCase()===c.toLowerCase()||(!x.dosageCategory&&current.toLowerCase().includes(c.toLowerCase()))?'selected':''}>${esc(c)}</option>`).join('')}</select></div>`}
function wineFormatField(x){const formats=[['37,5 cl','Mezza bottiglia','0,375 L'],['75 cl','Bottiglia','0,75 L'],['1,5 L','Magnum','1,5 L'],['3 L','Jeroboam','3 L']];const current=String(x.format||'75 cl');return `<div class="field"><label>FORMATO</label><select name="format">${formats.map(([value,name,litres])=>`<option value="${value}" ${current===value?'selected':''}>${name} — ${litres}</option>`).join('')}</select></div>`}
const STYLE_IT={fresh:'Fresco',mineral:'Minerale',elegant:'Elegante',creamy:'Cremoso',complex:'Complesso',vertical:'Verticale',aromatic:'Aromatico',savoury:'Sapido',soft:'Morbido',structured:'Strutturato',fruity:'Fruttato',spicy:'Speziato',evolved:'Evoluto',floral:'Floreale'};
function styleIt(v){return STYLE_IT[String(v||'').toLowerCase()]||String(v||'')}
function styleId(v){const raw=String(v||'').toLowerCase(),byId=(wineLib().styles||[]).find(st=>st.id===raw),byLabel=(wineLib().styles||[]).find(st=>st.label.toLowerCase()===raw);if(byId)return byId.id;if(byLabel)return byLabel.id;const translated=styleIt(v).toLowerCase();const found=(wineLib().styles||[]).find(st=>st.label.toLowerCase()===translated);return found?found.id:raw}

function champagneMention(x){if(x.type!=='sparkling'||x.country!=='france'||String(x.denomination).toLowerCase()!=='champagne')return '';const vals=['Nessuna','Premier Cru','Grand Cru','Altro'];return `<div class="field champagne-mention"><label>CLASSIFICAZIONE / MENZIONE</label><select name="champagneMention">${vals.map(v=>`<option value="${v==='Nessuna'?'':v}" ${(x.champagneMention||'')===(v==='Nessuna'?'':v)?'selected':''}>${v}</option>`).join('')}</select></div>`}

const icon={edit:'<svg viewBox="0 0 24 24"><path d="M4 20l4.2-1 10.6-10.6-3.2-3.2L5 15.8 4 20zM13.8 7l3.2 3.2"/></svg>',trash:'<svg viewBox="0 0 24 24"><path d="M5 7h14M9 7V4h6v3M8 10v7M12 10v7M16 10v7M7 7l1 13h8l1-13"/></svg>',eye:'<svg viewBox="0 0 24 24"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6z"/><circle cx="12" cy="12" r="2.5"/></svg>',grip:'<svg viewBox="0 0 24 24"><circle cx="9" cy="6" r="1"/><circle cx="15" cy="6" r="1"/><circle cx="9" cy="12" r="1"/><circle cx="15" cy="12" r="1"/><circle cx="9" cy="18" r="1"/><circle cx="15" cy="18" r="1"/></svg>'};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const slug=s=>String(s||'prodotto').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'prodotto';
async function loadDataset(k){const saved=localStorage.getItem(STORE[k]);if(saved){try{return JSON.parse(saved)}catch{localStorage.removeItem(STORE[k])}}const r=await fetch(SOURCE[k],{cache:'no-store'});if(!r.ok)throw new Error(`${k}: ${r.status} ${r.statusText}`);return r.json()}
function sanitizeFoodDataset(){const moved=new Set(['bevande','amari']);datasets.food.categories=(datasets.food.categories||[]).filter(c=>!moved.has(c.id));datasets.food.products=(datasets.food.products||[]).filter(p=>!moved.has(p.category));localStorage.setItem(STORE.food,JSON.stringify(datasets.food))}
async function init(){datasets.food=await loadDataset('food');datasets.wine=await loadDataset('wine');datasets.drinks=await loadDataset('drinks');try{datasets.catalog=await (await fetch(SOURCE.catalog)).json()}catch{datasets.catalog={wines:[]}}sanitizeFoodDataset();ensureTags();ensureWineLib();bind();renderCategoryFilters();renderCountryFilters();renderList()}
function items(){return kind==='food'?datasets.food.products:kind==='wine'?datasets.wine.wines:datasets.drinks.products}
function persist(k=kind){localStorage.setItem(STORE[k],JSON.stringify(datasets[k]))}
function ensureTags(){if(localStorage.getItem(STORE.tags))return;const tags=[...new Set((datasets.food.products||[]).flatMap(p=>p.tags||[]))];localStorage.setItem(STORE.tags,JSON.stringify(tags.length?tags:['vegetariano','vegano','senza-glutine','crudo','piccante']))}
function getTags(){try{return JSON.parse(localStorage.getItem(STORE.tags)||'[]')}catch{return []}}
function saveTags(tags){localStorage.setItem(STORE.tags,JSON.stringify(tags))}
function bind(){$$('.admin-tab').forEach(b=>b.onclick=()=>switchKind(b.dataset.kind));$('#productSearch').oninput=renderList;$('#coverCreate').onclick=createNew;$('#mobileCreate').onclick=createNew;$('#cancelEdit').onclick=closeEditor;$('#productForm').onsubmit=saveForm;$('#confirmCancel').onclick=closeConfirm;$('#confirmBackdrop').onclick=e=>{if(e.target.id==='confirmBackdrop')closeConfirm()};$('#confirmDelete').onclick=deleteConfirmed}
function switchKind(k){kind=k;document.body.dataset.kind=k;selectedId=null;$$('.admin-tab').forEach(b=>b.classList.toggle('is-active',b.dataset.kind===k));const isFood=k==='food',isWine=k==='wine';$('#listTitle').textContent=isFood?'Menu cibo':isWine?'Carta vini':'Bevande';$('#listEyebrow').textContent=isWine?'BOTTIGLIE':'PRODOTTI';$('#coverCreateLabel').textContent=isFood?'NUOVO PIATTO':isWine?'NUOVA BOTTIGLIA':'NUOVA BEVANDA';$('#coverCreate').setAttribute('aria-label',isFood?'Nuovo piatto':isWine?'Nuova bottiglia':'Nuova bevanda');$('#mobileCreateLabel').textContent=isFood?'NUOVO PIATTO':isWine?'NUOVA BOTTIGLIA':'NUOVA BEVANDA';$('#mobileCreate').setAttribute('aria-label',isFood?'Nuovo piatto':isWine?'Nuova bottiglia':'Nuova bevanda');$('#mobileCreate').className=`mobile-create-card mobile-create-card--${isFood?'food':isWine?'wine':'drinks'}`;$('#emptyEditor').classList.toggle('empty-editor--food',isFood);$('#emptyEditor').classList.toggle('empty-editor--wine',isWine);$('#emptyEditor').classList.toggle('empty-editor--drinks',k==='drinks');$('#productSearch').value='';closeEditor();renderCategoryFilters();renderCountryFilters();renderList()}
function categoryOptions(){return kind==='food'?(datasets.food.categories||[]).map(c=>({id:c.id,label:c.name?.it||c.id.toUpperCase()})):kind==='wine'?WINE_CATEGORIES:DRINK_CATEGORIES}
function renderCategoryFilters(){const host=$('#categoryFilters'),opts=[{id:'all',label:'TUTTI'},...categoryOptions()];host.innerHTML=opts.map(c=>`<button type="button" class="category-filter ${activeCategory[kind]===c.id?'is-active':''}" data-category="${esc(c.id)}">${esc(c.label)}</button>`).join('');$$('#categoryFilters .category-filter').forEach(b=>b.onclick=()=>{activeCategory[kind]=b.dataset.category;renderCategoryFilters();renderCountryFilters();renderList()})}
function renderCountryFilters(){const host=$('#countryFilters');if(kind!=='wine'){host.hidden=true;host.innerHTML='';return}host.hidden=false;host.innerHTML=WINE_COUNTRIES.map(c=>`<button type="button" class="country-filter ${activeWineCountry===c.id?'is-active':''}" data-country="${c.id}">${c.label}</button>`).join('');$$('#countryFilters .country-filter').forEach(b=>b.onclick=()=>{activeWineCountry=b.dataset.country;renderCountryFilters();renderList()})}
function matchesWineCountry(x){if(activeWineCountry==='all')return true;if(activeWineCountry==='rest')return !['italy','france','spain'].includes(String(x.country||'').toLowerCase());return String(x.country||'').toLowerCase()===activeWineCountry}
function filtered(){const q=$('#productSearch').value.trim().toLowerCase(),cat=activeCategory[kind];return items().filter(x=>(cat==='all'||(kind==='food'||kind==='drinks'?x.category:x.type)===cat)&&(kind!=='wine'||matchesWineCountry(x))&&[x.name?.it,x.producer,x.id].some(v=>String(v||'').toLowerCase().includes(q))).sort((a,b)=>(a.order??999)-(b.order??999))}
function renderList(){const list=filtered(),canDrag=activeCategory[kind]!=='all'&&!$('#productSearch').value&&!(kind==='wine'&&activeWineCountry!=='all');$('#productCount').textContent=`${list.length} / ${items().length}`;$('#productList').innerHTML=list.map(x=>`<div class="product-row ${x.active===false?'is-hidden':''} ${x.id===selectedId?'is-selected':''} ${canDrag?'is-draggable':''}" data-id="${esc(x.id)}" draggable="${canDrag}"><button class="drag-handle" type="button" title="Trascina per riordinare" ${canDrag?'':'disabled'}>${icon.grip}</button><div class="product-thumb ${x.image?'':'is-empty'}">${x.image?`<img src="${esc(x.image)}" alt="">`:'<span>·</span>'}</div><div class="product-main"><div class="product-name">${esc(x.name?.it||x.id)}</div><div class="product-meta">${kind==='food'||kind==='drinks'?esc(x.category):esc([x.producer,x.denomination].filter(Boolean).join(' · '))}</div></div><div class="row-actions"><span class="visibility-dot"></span><button class="icon-btn hide" type="button">${icon.eye}</button><button class="icon-btn edit" type="button">${icon.edit}</button><button class="icon-btn delete" type="button">${icon.trash}</button></div></div>`).join('');$$('.product-row').forEach(r=>{r.querySelector('.product-main').onclick=()=>openEdit(r.dataset.id);r.querySelector('.edit').onclick=()=>openEdit(r.dataset.id);r.querySelector('.hide').onclick=()=>toggleVisibility(r.dataset.id);r.querySelector('.delete').onclick=()=>askDelete(r.dataset.id);if(canDrag){r.ondragstart=()=>{dragId=r.dataset.id;r.classList.add('is-dragging')};r.ondragend=()=>{dragId=null;r.classList.remove('is-dragging');$$('.product-row').forEach(x=>x.classList.remove('drag-over'))};r.ondragover=e=>{e.preventDefault();if(r.dataset.id!==dragId)r.classList.add('drag-over')};r.ondragleave=()=>r.classList.remove('drag-over');r.ondrop=e=>{e.preventDefault();r.classList.remove('drag-over');reorder(dragId,r.dataset.id)}}})}
function reorder(fromId,toId){if(!fromId||fromId===toId)return;const visible=filtered(),ids=visible.map(x=>x.id),from=ids.indexOf(fromId),to=ids.indexOf(toId);if(from<0||to<0)return;ids.splice(to,0,ids.splice(from,1)[0]);ids.forEach((id,i)=>{const x=items().find(p=>p.id===id);if(x)x.order=i+1});persist();renderList();toast('Ordine aggiornato')}
function normalizeCategory(cat){const arr=items().filter(x=>(kind==='food'||kind==='drinks'?x.category:x.type)===cat).sort((a,b)=>(a.order??999)-(b.order??999));arr.forEach((x,i)=>x.order=i+1)}
function toggleVisibility(id){const x=items().find(i=>i.id===id);x.active=x.active===false;persist();renderList();toast(x.active?'Prodotto visibile':'Prodotto nascosto');if(selectedId===id)$('#field-active').checked=x.active}
function askDelete(id){const x=items().find(i=>i.id===id);pendingDelete=id;$('#confirmTitle').textContent=`Eliminare “${x.name?.it||id}”?`;$('#confirmText').textContent='Questa operazione rimuove il prodotto. Per renderlo temporaneamente non disponibile usa Nascondi.';$('#confirmBackdrop').hidden=false}
function closeConfirm(){$('#confirmBackdrop').hidden=true;pendingDelete=null}
function deleteConfirmed(){if(!pendingDelete)return;const arr=items(),x=arr.find(p=>p.id===pendingDelete),i=arr.findIndex(p=>p.id===pendingDelete);if(i>=0)arr.splice(i,1);if(x)normalizeCategory(kind==='food'||kind==='drinks'?x.category:x.type);if(selectedId===pendingDelete)closeEditor();persist();renderList();closeConfirm();toast('Prodotto eliminato')}
function scrollEditorTop(){const panel=$('.editor-panel');const top=panel.getBoundingClientRect().top+window.scrollY-12;window.scrollTo({top:Math.max(0,top),behavior:'smooth'});panel.scrollTo({top:0,behavior:'smooth'})}
function openEdit(id){document.body.classList.add('is-editing');selectedId=id;const existing=items().find(i=>i.id===id);if(existing)newDraft=null;const x=existing||(newDraft&&newDraft.id===id?newDraft:null);if(!x)return;$('#emptyEditor').hidden=true;$('#productForm').hidden=false;$('#editorEyebrow').textContent=kind==='food'?'MODIFICA PIATTO':kind==='wine'?'MODIFICA BOTTIGLIA':'MODIFICA BEVANDA';$('#editorTitle').textContent=x.name?.it||x.id;$('#field-active').checked=x.active!==false;$('#formFields').innerHTML=kind==='food'?foodFields(x):kind==='wine'?wineFields(x):drinkFields(x);wireDynamicFields();renderList();requestAnimationFrame(scrollEditorTop)}
