function uniqueId(name){let base=slug(name),id=base,n=2;while(items().some(x=>x.id===id))id=`${base}-${n++}`;return id}
function createNew(){let cat=activeCategory[kind];if(cat==='all')cat=kind==='food'?(datasets.food.categories?.[0]?.id||'antipasti'):kind==='wine'?'sparkling':'bevande';if(kind==='food')newDraft={id:uniqueId('nuovo-piatto'),category:cat,active:true,order:1,name:{it:'Nuovo piatto',en:'',es:''},shortDescription:{it:'',en:'',es:''},description:{it:'',en:'',es:''},price:0,image:'',ingredients:{it:'',en:'',es:''},allergens:[],tags:[],winePairings:[],recommendedBefore:[],recommendedAfter:[],featured:false,images:[]};else if(kind==='wine')newDraft={id:uniqueId('nuova-bottiglia'),type:cat,country:activeWineCountry==='all'||activeWineCountry==='rest'?'italy':activeWineCountry,region:'',denomination:'',producer:'',vintage:'NV',grapes:[],style:[],dosage:'',aging:'',format:'75 cl',price:0,active:true,order:1,name:{it:'Nuova bottiglia',en:'',es:''},shortDescription:{it:'',en:'',es:''},description:{it:'',en:'',es:''},foodPairings:[],image:''};else newDraft={id:uniqueId('nuova-bevanda'),category:cat,active:true,order:1,name:{it:'Nuova bevanda',en:'',es:''},shortDescription:{it:'',en:'',es:''},description:{it:'',en:'',es:''},price:0,format:'',alcohol:'',image:'',images:[]};openEdit(newDraft.id)}
function input(name,label,value,type='text',full=false,help=''){return `<div class="field ${full?'full':''}"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}">${help?`<small>${help}</small>`:''}</div>`}
