function langs(obj,prefix,label,textarea=false,help=''){const ls=contentLanguages();return `<section class="form-section"><h3 class="form-section-title">${label}</h3><div class="field-grid three">${ls.map(l=>textarea?area(`${prefix}.${l}`,LANGUAGE_CATALOG[l]||l.toUpperCase(),obj?.[l]||'',false,help):input(`${prefix}.${l}`,LANGUAGE_CATALOG[l]||l.toUpperCase(),obj?.[l]||'')).join('')}</div></section>`}
function aiDescriptions(obj,{ingredients=false}={}){const ls=contentLanguages();const langButtons=ls.map(l=>`<button type="button" class="ai-lang-tab ${l==='it'?'is-active':''}" data-ai-lang="${l}">${l.toUpperCase()}</button>`).join('');const panels=ls.map(l=>`<div class="ai-lang-panel ${l==='it'?'is-active':''}" data-ai-panel="${l}"><div class="field full ai-name-field"><label>NOME</label><input name="name.${l}" type="text" value="${esc(obj.name?.[l]||'')}"></div>${ingredients?`<div class="field full ai-ingredients-field"><label>INGREDIENTI</label><textarea name="ingredients.${l}" rows="2" placeholder="Inserisci gli ingredienti separandoli con una virgola.">${esc(obj.ingredients?.[l]||'')}</textarea></div>`:''}<div class="field"><label>DESCRIZIONE BREVE</label><textarea name="shortDescription.${l}" rows="3">${esc(obj.shortDescription?.[l]||'')}</textarea></div><div class="field"><label>DESCRIZIONE</label><textarea name="description.${l}" rows="6">${esc(obj.description?.[l]||'')}</textarea></div></div>`).join('');return `<section class="form-section ai-copy-section"><div class="section-title-row"><div><h3 class="form-section-title">CONTENUTI</h3><p class="ai-copy-help">Gestisci nome, descrizioni${ingredients?' e ingredienti':''} del prodotto nelle lingue attive. L'AI può generare le descrizioni e tradurre automaticamente i contenuti.</p></div></div><div class="ai-lang-tabs-row"><div class="ai-lang-tabs">${langButtons}</div><button type="button" class="text-action manage-content-languages" id="manageContentLanguages">＋ LINGUE</button></div>${panels}<div class="ai-copy-toolbar"><button type="button" class="ai-action primary" id="aiGenerateCopy"><span>✦</span> GENERA DESCRIZIONI</button><button type="button" class="ai-action" id="aiTranslateCopy"><span>✦</span> TRADUCI CONTENUTI</button><span class="ai-status" id="aiCopyStatus"></span></div></section>`}
function descriptionFields(x,options){return aiDescriptions(x,options)}
function arr(name,label,v,help='Separa i valori con una virgola'){return input(name,label,(v||[]).join(', '),'text',true,help)}
function toggleField(name,label,on){return `<div class="field"><label>${label}</label><label class="switch-field"><input type="checkbox" name="${name}" ${on?'checked':''}><span></span><b>${on?'SÌ':'NO'}</b></label></div>`}
function imageUploader(name,label,current){return `<div class="field full image-upload"><label>${label}</label><input type="hidden" name="${name}" value="${esc(current||'')}"><div class="upload-row"><label class="upload-button">CARICA FILE<input type="file" data-image-target="${name}" accept="image/*"></label><span class="upload-name">${current?esc(current.split('/').pop()):'Nessun file selezionato'}</span></div><div class="image-preview ${current?'has-image':''}" data-preview="${name}">${current?`<img src="${esc(current)}" alt="">`:''}</div></div>`}
function galleryFields(x){const extras=(x.images||[]).filter(Boolean).filter(p=>p!==x.image).slice(0,3),on=extras.length>0;return `<section class="form-section"><h3 class="form-section-title">IMMAGINI</h3><div class="field-grid">${imageUploader('image','IMMAGINE PRINCIPALE',x.image)}${toggleField('galleryEnabled','GALLERIA',on)}<div class="gallery-extra full" ${on?'':'hidden'}>${[0,1,2].map(i=>imageUploader(`gallery.${i}`,`IMMAGINE ${i+1}`,extras[i]||'')).join('')}</div></div></section>`}
function tagsField(x){const tags=getTags(),selected=x.tags||[],opts=tags.map(t=>({value:t,label:t.replace(/-/g,' ')}));return `<section class="form-section"><div class="section-title-row"><h3 class="form-section-title">CARATTERISTICHE</h3><button type="button" class="text-action" id="manageTags">＋ GESTISCI CARATTERISTICHE</button></div><button type="button" class="field-selector" id="foodTagsSelector"><span>SELEZIONA CARATTERISTICHE</span><b>⌄</b></button><div class="selector-summary" id="foodTagsSummary">${selectorSummary(opts.filter(o=>selected.includes(o.value)).map(o=>o.label))}</div>${hiddenChecks('tags',opts,selected)}</section>`}
function relationRows(name,ids,targetKind){const targets=targetKind==='food'?datasets.food.products:datasets.wine.wines,limited=(ids||[]).slice(0,4);return `<div class="relation-builder" data-relation="${name}" data-target="${targetKind}"><div class="relation-rows">${limited.map(id=>relationRow(name,id,targetKind,targets)).join('')}</div><button type="button" class="text-action add-relation">＋ AGGIUNGI</button><span class="relation-limit">${limited.length}/4</span></div>`}
function relationRow(name,id,targetKind,targets){const target=targets.find(x=>x.id===id),cat=target?(targetKind==='food'?target.category:target.type):'all';const cats=targetKind==='food'?(datasets.food.categories||[]).map(c=>({id:c.id,label:c.name?.it||c.id})):WINE_CATEGORIES;const available=targets.filter(x=>(targetKind==='food'?x.category:x.type)===cat);return `<div class="relation-row"><select class="rel-category">${cats.map(c=>`<option value="${c.id}" ${c.id===cat?'selected':''}>${esc(c.label)}</option>`).join('')}</select><select class="rel-product" name="${name}">${available.map(x=>`<option value="${esc(x.id)}" ${x.id===id?'selected':''}>${esc(x.name?.it||x.producer||x.id)}</option>`).join('')}</select><button type="button" class="remove-relation">×</button></div>`}
function foodFields(x){const cats=datasets.food.categories||[];return `<section class="form-section"><h3 class="form-section-title">DATI PRINCIPALI</h3><div class="field-grid">${select('category','CATEGORIA',x.category,cats)}<div class="mobile-pair-row">${input('price','PREZZO €',x.price,'number')}<div class="field"><label>IN EVIDENZA</label><select name="featured"><option value="false" ${!x.featured?'selected':''}>No</option><option value="true" ${x.featured?'selected':''}>Sì</option></select></div></div></div></section>${galleryFields(x)}${descriptionFields(x,{ingredients:true})}${tagsField(x)}<section class="form-section"><h3 class="form-section-title">ALLERGENI</h3>${arr('allergens','ALLERGENI',x.allergens)}</section><section class="form-section"><h3 class="form-section-title">ABBINAMENTI</h3><div class="relation-group"><label>VINI CONSIGLIATI</label>${relationRows('winePairings',x.winePairings,'wine')}</div><div class="relation-group"><label>CONSIGLIATO PRIMA</label>${relationRows('recommendedBefore',x.recommendedBefore,'food')}</div><div class="relation-group"><label>CONSIGLIATO DOPO</label>${relationRows('recommendedAfter',x.recommendedAfter,'food')}</div></section>`}
function drinkFields(x){const cats=(datasets.drinks.categories||[]);const alcoholic=['amari','birre','distillati'].includes(x.category);return `<section class="form-section"><h3 class="form-section-title">DATI PRINCIPALI</h3><div class="field-grid">${select('category','CATEGORIA',x.category,cats)}<div class="mobile-pair-row">${input('format','FORMATO',x.format||'')}${input('price','PREZZO €',x.price,'number')}</div>${alcoholic?input('alcohol','GRADAZIONE %',x.alcohol||'','number'):''}</div></section>${galleryFields(x)}${descriptionFields(x)}`}
function wineCatalogTools(){return `<section class="form-section wine-catalog-tools"><div class="section-title-row"><div><h3 class="form-section-title">CATALOGO VINO</h3><p class="catalog-help">Trova una referenza nel catalogo proprietario oppure acquisisci l'etichetta. La foto identifica il vino; il match finale viene effettuato esclusivamente sul nostro catalogo.</p></div></div><div class="catalog-actions"><div class="catalog-search-wrap"><input id="wineCatalogSearch" type="search" placeholder="Cerca produttore, vino, denominazione…"><button type="button" class="btn ghost" id="wineCatalogSearchBtn">CERCA</button></div><button type="button" class="catalog-scan-btn" id="wineScanOpen"><span class="catalog-camera">⌁</span><b>SCANSIONA ETICHETTA</b></button></div><input id="wineLabelCamera" class="catalog-file-input" type="file" accept="image/*" capture="environment"><input id="wineLabelLibrary" class="catalog-file-input" type="file" accept="image/*"><div id="wineCatalogResults" class="catalog-results" hidden></div></section>`}
function wineFields(x){const l=wineLib(),countries=l.countries,regions=l.regions[x.country]||[],denoms=l.denominations[denomKey(x.country,x.type,x.region)]||[],producers=l.producers[producerKey(x.country,x.type,x.region,x.denomination)]||[];const countryField=libSelect('country','PAESE',countries.map(c=>c.label),countries.find(c=>c.id===x.country)?.label||x.country,'country'),regionField=x.type==='sparkling'?'':libSelect('region','REGIONE',regions,x.region,'region'),denomField=libSelect('denomination','DENOMINAZIONE',denoms,x.denomination,'denomination'),producerField=libSelect('producer','PRODUTTORE',producers,x.producer,'producer');return `${wineCatalogTools()}<section class="form-section"><h3 class="form-section-title">IDENTITÀ DEL VINO</h3><div class="field-grid wine-identity-grid"><div class="mobile-pair-row">${select('type','TIPO',x.type,WINE_CATEGORIES)}${countryField}</div>${regionField}<div class="mobile-pair-row">${denomField}${producerField}</div><div class="mobile-pair-row wine-vintage-dosage">${vintageField(x)}${dosageField(x)}</div>${champagneMention(x)}<div class="mobile-pair-row">${wineFormatField(x)}${input('price','PREZZO €',x.price,'number')}</div></div></section>${grapesField(x)}${agingField(x)}${wineStylesField(x)}${galleryFields(x)}${descriptionFields(x)}<section class="form-section"><h3 class="form-section-title">PERFETTO CON</h3>${relationRows('foodPairings',x.foodPairings,'food')}</section>`}
function wireFoodTagsSelector(){const btn=$('#foodTagsSelector');if(!btn)return;const tags=getTags(),inputs=[...document.querySelectorAll('input[name="tags"]')];btn.onclick=()=>openMultiSelector({title:'CARATTERISTICHE',options:tags.map(t=>({value:t,label:t.replace(/-/g,' ')})),selected:inputs.filter(i=>i.checked).map(i=>i.value),onApply:values=>{inputs.forEach(i=>i.checked=values.includes(i.value));$('#foodTagsSummary').innerHTML=selectorSummary(tags.filter(t=>values.includes(t)).map(t=>t.replace(/-/g,' ')))}})}
function wireDynamicFields(){const g=$('input[name="galleryEnabled"]');if(g)g.onchange=()=>{const box=$('.gallery-extra');box.hidden=!g.checked;g.closest('.switch-field').querySelector('b').textContent=g.checked?'SÌ':'NO'};$$('[data-image-target]').forEach(inp=>inp.onchange=()=>previewFile(inp));$('#manageTags')?.addEventListener('click',openTagManager);$('#manageWineStyles')?.addEventListener('click',openWineStyleManager);$('#addGrape')?.addEventListener('click',addGrapePrompt);wireGrapeTypes();wireWineStyleSelector();wireFoodTagsSelector();$$('.relation-builder').forEach(wireRelationBuilder);wireWineHierarchy();wireAging();wireWineCatalog();const wt=$('select[name="type"]');if(wt)wt.onchange=()=>{const x=newDraft&&newDraft.id===selectedId?newDraft:items().find(i=>i.id===selectedId);if(!x)return;const draft=captureFormDraft();x.type=wt.value;x.region='';x.denomination='';x.producer='';if(draft){draft.values.type=wt.value;delete draft.values.region;delete draft.values.denomination;delete draft.values.producer}openEdit(selectedId);requestAnimationFrame(()=>restoreFormDraft(draft))};const vm=$('select[name="vintageMode"]');if(vm)vm.onchange=()=>{$('.vintage-year').hidden=vm.value!=='vintage'};const nv=$('input[name="noVintage"]');if(nv)nv.onchange=()=>{const y=$('input[name="vintageYear"]');y.disabled=nv.checked;nv.closest('.switch-field').querySelector('b').textContent=nv.checked?'SÌ':'NO'};wireAiDescriptions()}
function catalogLabel(w){return [w.producer,w.name?.it,w.vintage&&w.vintage!=='NV'?w.vintage:null,w.denomination].filter(Boolean).join(' · ')}
function catalogScore(w,q){const tokens=String(q||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/[^a-z0-9]+/).filter(t=>t.length>1);if(!tokens.length)return 0;const hay=[w.producer,w.name?.it,w.vintage,w.denomination,w.region,...(w.searchAliases||[])].filter(Boolean).join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');return tokens.reduce((n,t)=>n+(hay.includes(t)?1:0),0)/tokens.length}
function renderCatalogMatches(matches,message=''){const host=$('#wineCatalogResults');if(!host)return;host.hidden=false;host.innerHTML=`${message?`<p class="catalog-result-message">${esc(message)}</p>`:''}${matches.length?matches.map(({w,score})=>`<button type="button" class="catalog-match" data-catalog-id="${esc(w.catalogId||w.id)}"><span><b>${esc(w.producer||'')}</b><strong>${esc(w.name?.it||'')}</strong><small>${esc([w.vintage,w.denomination].filter(Boolean).join(' · '))}</small></span><em>${Math.round(score*100)}% MATCH</em></button>`).join(''):'<div class="catalog-empty"><b>NESSUN MATCH NEL CATALOGO</b><span>Puoi continuare con l’inserimento manuale. In futuro la nuova referenza potrà essere validata e aggiunta al catalogo centrale.</span></div>'}`;host.querySelectorAll('.catalog-match').forEach(b=>b.onclick=()=>applyCatalogWine(b.dataset.catalogId))}
function searchWineCatalog(q){const wines=datasets.catalog?.wines||[];const matches=wines.map(w=>({w,score:catalogScore(w,q)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,5);renderCatalogMatches(matches,matches.length?'REFERENZE TROVATE NEL CATALOGO':'')}
function applyCatalogWine(id){const c=(datasets.catalog?.wines||[]).find(w=>(w.catalogId||w.id)===id);if(!c)return;const x=newDraft&&newDraft.id===selectedId?newDraft:items().find(i=>i.id===selectedId);if(!x)return;const preserve={id:x.id,price:x.price,active:x.active,order:x.order,foodPairings:x.foodPairings||[]};Object.assign(x,structuredClone(c),preserve,{catalogId:c.catalogId||c.id});openEdit(selectedId);toast('Dati importati dal Catalogo Vino')}
function showWineScanChooser(){if(!window.matchMedia('(max-width:760px)').matches){$('#wineLabelLibrary')?.click();return}const wrap=document.createElement('div');wrap.className='modal-backdrop dynamic-modal';wrap.innerHTML=`<div class="confirm-box wine-scan-chooser"><p class="eyebrow">CATALOGO VINO</p><h2>Scansiona una bottiglia</h2><p class="manager-help">Fotografa l'etichetta oppure scegli un'immagine già presente sul telefono.</p><div class="wine-scan-options"><button type="button" class="wine-scan-option" data-camera><span>⌁</span><b>SCATTA FOTO</b><small>Apri la fotocamera</small></button><button type="button" class="wine-scan-option" data-library><span>▧</span><b>SCEGLI DALLA LIBRERIA</b><small>Usa una foto esistente</small></button></div><button type="button" class="btn ghost wine-scan-cancel" data-close>ANNULLA</button></div>`;document.body.appendChild(wrap);const close=()=>wrap.remove();wrap.querySelector('[data-close]').onclick=close;wrap.onclick=e=>{if(e.target===wrap)close()};wrap.querySelector('[data-camera]').onclick=()=>{close();$('#wineLabelCamera')?.click()};wrap.querySelector('[data-library]').onclick=()=>{close();$('#wineLabelLibrary')?.click()}}
async function scanWineLabel(file){const host=$('#wineCatalogResults');if(!host)return;host.hidden=false;host.innerHTML='<div class="catalog-scanning"><span></span><b>PREPARAZIONE ETICHETTA…</b><small>Il riconoscimento fotografico richiede il servizio Vision collegato via API.</small></div>';try{const fd=new FormData();fd.append('image',file);const r=await fetch('/api/wine-label',{method:'POST',body:fd});if(!r.ok)throw new Error('vision-unavailable');const data=await r.json();const query=[data.producer,data.name,data.vintage,data.denomination].filter(Boolean).join(' ');if(!query)throw new Error('vision-empty');const wines=datasets.catalog?.wines||[];const matches=wines.map(w=>({w,score:catalogScore(w,query)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,3);if(!matches.length)renderCatalogMatches([],`Etichetta riconosciuta: “${query}”. Nessuna referenza corrispondente nel catalogo.`);else renderCatalogMatches(matches,`Possibili corrispondenze per “${query}”. Verifica prima di importare.`)}catch{host.innerHTML='<div class="catalog-empty catalog-vision-off"><b>RICONOSCIMENTO ETICHETTA NON ANCORA ATTIVO</b><span>La foto è pronta, ma il servizio Vision deve ancora essere collegato tramite API. Puoi usare la ricerca nel Catalogo Vino oppure continuare con l’inserimento manuale.</span></div>'}}
function wireWineCatalog(){const search=$('#wineCatalogSearch'),btn=$('#wineCatalogSearchBtn'),open=$('#wineScanOpen'),camera=$('#wineLabelCamera'),library=$('#wineLabelLibrary');if(btn)btn.onclick=()=>searchWineCatalog(search.value);if(search)search.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();searchWineCatalog(search.value)}};if(open)open.onclick=showWineScanChooser;[camera,library].forEach(input=>{if(input)input.onchange=()=>{const f=input.files?.[0];if(f)scanWineLabel(f);input.value=''}})}
