function countryIdFromLabel(label){const l=wineLib();return l.countries.find(c=>c.label===label)?.id||slug(label)}
function wireWineHierarchy(){$$('.wine-lib-select').forEach(sel=>sel.onchange=()=>{if(sel.value==='__add__'){const v=prompt(`Nuovo ${sel.dataset.addKind}:`);if(v){addWineLibraryValue(sel.dataset.addKind,v);openEdit(selectedId)}else openEdit(selectedId);return}if(['country','region','denomination'].includes(sel.name)){const x=newDraft&&newDraft.id===selectedId?newDraft:items().find(i=>i.id===selectedId);if(!x)return;if(sel.name==='country'){x.country=countryIdFromLabel(sel.value);x.region='';x.denomination='';x.producer=''}if(sel.name==='region'){x.region=sel.value;x.denomination='';x.producer=''}if(sel.name==='denomination'){x.denomination=sel.value;x.producer=''}const draft=captureFormDraft();openEdit(selectedId);requestAnimationFrame(()=>restoreFormDraft(draft))}})}
function addWineLibraryValue(kindName,value){const l=wineLib(),form=$('#productForm'),type=form.elements.type?.value||'sparkling',country=countryIdFromLabel(form.elements.country?.value||'Italia'),region=form.elements.region?.value||'',denom=form.elements.denomination?.value||'';if(kindName==='country'){const id=slug(value);if(!l.countries.some(c=>c.id===id))l.countries.push({id,label:value})}else if(kindName==='region'){const a=l.regions[country]||(l.regions[country]=[]);if(!a.includes(value))a.push(value)}else if(kindName==='denomination'){const a=l.denominations[denomKey(country,type,region)]||(l.denominations[denomKey(country,type,region)]=[]);if(!a.includes(value))a.push(value)}else if(kindName==='producer'){const a=l.producers[producerKey(country,type,region,denom)]||(l.producers[producerKey(country,type,region,denom)]=[]);if(!a.includes(value))a.push(value)}saveWineLib(l)}
