 modal.querySelectorAll('.style-save').forEach(b=>b.onclick=()=>{const row=b.closest('.wine-style-manage-row'),id=row.dataset.styleId,label=row.querySelector('.style-name').value.trim(),descs=[...row.querySelectorAll('.style-desc')].map(x=>x.value.trim());if(!label||descs.some(x=>!x)){alert('Nome e tre aggettivi sono obbligatori.');return}const st=l.styles.find(x=>x.id===id);if(!st)return;st.label=label;st.descriptors=descs;saveWineLib(l);toast('Stile e Wine Guide aggiornati');rerender()});
