function captureFormDraft(){
 const form=$('#productForm'); if(!form||form.hidden)return null;
 const draft={values:{},checks:{},relations:{},active:$('#field-active').checked};
 [...form.elements].forEach(el=>{if(!el.name||el.type==='file')return;if(el.type==='checkbox')draft.checks[el.name]=(draft.checks[el.name]||[]).concat(el.checked?el.value||'on':[]);else draft.values[el.name]=el.value});
 ['winePairings','recommendedBefore','recommendedAfter','foodPairings'].forEach(n=>draft.relations[n]=[...form.querySelectorAll(`select[name="${n}"]`)].map(x=>x.value));
 return draft;
}
function restoreFormDraft(draft){
 if(!draft)return; const form=$('#productForm'); $('#field-active').checked=draft.active;
 Object.entries(draft.values||{}).forEach(([n,v])=>{const el=form.elements[n];if(el&&!['winePairings','recommendedBefore','recommendedAfter','foodPairings'].includes(n))el.value=v});
 form.querySelectorAll('input[name="tags"]').forEach(el=>el.checked=(draft.checks.tags||[]).includes(el.value));
 const g=form.elements.galleryEnabled;if(g){g.checked=(draft.checks.galleryEnabled||[]).length>0;g.dispatchEvent(new Event('change'))}
}
