function getVal(form,name){const el=form.elements[name];return el?el.value:''}
function setPath(obj,path,val){const p=path.split('.');let o=obj;while(p.length>1){const k=p.shift();o=o[k]||(o[k]={})}o[p[0]]=val}
function readRelations(form,name){return [...form.querySelectorAll(`select[name="${name}"]`)].map(s=>s.value).filter(Boolean)}
function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function imageValue(form,name){const hidden=form.elements[name],file=form.querySelector(`[data-image-target="${CSS.escape(name)}"]`)?.files?.[0];return file?await readFile(file):(hidden?.value||'')}

function aiContext(form){
 const name=contentLanguages().map(l=>getVal(form,`name.${l}`)).find(Boolean)||'';
 const payload={kind,name,category:getVal(form,'category')||getVal(form,'type')||'',language:'it'};
 if(kind==='food')payload.ingredients=getVal(form,'ingredients.it')||'';
 if(kind==='wine')Object.assign(payload,{producer:getVal(form,'producer'),denomination:getVal(form,'denomination'),grapes:[...form.querySelectorAll('input[name="wineGrape"]:checked')].map(i=>i.value),styles:[...form.querySelectorAll('input[name="wineStyle"]:checked')].map(i=>i.value),aging:[...form.querySelectorAll('.aging-row')].map(r=>({vessel:r.querySelector('[name="agingVessel"]')?.value,duration:r.querySelector('[name="agingDuration"]')?.value,unit:r.querySelector('[name="agingUnit"]')?.value}))});
 if(kind==='drinks')Object.assign(payload,{format:getVal(form,'format'),alcohol:getVal(form,'alcohol')});
 return payload
}
async function callAiContent(action,payload){
 try{
  const res=await fetch('/api/ai-content',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...payload})});
  if(!res.ok){
   let errorMsg='ai-error';
   try{const errorData=await res.json();if(errorData&&errorData.error)errorMsg=errorData.error}catch{}
   const err=new Error(errorMsg);err.status=res.status;throw err
  }
  return await res.json()
 }catch(networkError){
  if(networkError.status)throw networkError;
  const err=new Error('Network error or server unreachable');err.status=0;throw err
 }
}
