function wireAiDescriptions(){ $$('.ai-lang-tab').forEach(b=>b.onclick=()=>{$$('.ai-lang-tab').forEach(x=>x.classList.toggle('is-active',x===b));$$('.ai-lang-panel').forEach(p=>p.classList.toggle('is-active',p.dataset.aiPanel===b.dataset.aiLang))});$('#aiGenerateCopy')&&($('#aiGenerateCopy').onclick=openAiStylePicker);$('#aiTranslateCopy')&&($('#aiTranslateCopy').onclick=translateAiCopy);$('#manageContentLanguages')&&($('#manageContentLanguages').onclick=openLanguageManager)}

async function saveForm(e){e.preventDefault();const isNew=!!(newDraft&&newDraft.id===selectedId);const x=isNew?newDraft:items().find(i=>i.id===selectedId);if(!x)return;const form=e.currentTarget,oldCat=kind==='food'||kind==='drinks'?x.category:x.type;if(kind==='food'){const common=['category','price','featured',...contentLanguages().flatMap(l=>[`name.${l}`,`shortDescription.${l}`,`description.${l}`,`ingredients.${l}`]),'allergens'];for(const f of common){let v=getVal(form,f);if(f==='price')v=Number(v);if(f==='allergens')v=v.split(',').map(s=>s.trim()).filter(Boolean);if(f==='featured')v=v==='true';setPath(x,f,v)}x.tags=[...form.querySelectorAll('input[name="tags"]:checked')].map(i=>i.value);x.winePairings=readRelations(form,'winePairings');x.recommendedBefore=readRelations(form,'recommendedBefore');x.recommendedAfter=readRelations(form,'recommendedAfter')}else if(kind==='wine'){const type=getVal(form,'type'),country=countryIdFromLabel(getVal(form,'country'));x.type=type;x.country=country;x.region=type==='sparkling'?'':getVal(form,'region');x.denomination=getVal(form,'denomination');x.producer=getVal(form,'producer');x.format=getVal(form,'format');x.price=Number(getVal(form,'price'));[...contentLanguages().flatMap(l=>[`name.${l}`,`shortDescription.${l}`,`description.${l}`])].forEach(f=>setPath(x,f,getVal(form,f)));if(type==='sparkling')x.vintage=getVal(form,'vintageMode')==='vintage'?getVal(form,'vintageYear'):'NV';else x.vintage=form.elements.noVintage?.checked?'NV':getVal(form,'vintageYear');x.grapes=[...form.querySelectorAll('input[name="wineGrape"]:checked')].map(i=>i.value);x.style=[...form.querySelectorAll('input[name="wineStyle"]:checked')].map(i=>i.value);x.dosage=type==='sparkling'?getVal(form,'dosageCategory'):'';x.dosageCategory=type==='sparkling'?getVal(form,'dosageCategory'):'';x.champagneMention=getVal(form,'champagneMention');x.agingSteps=[...form.querySelectorAll('.aging-row')].map(r=>({vessel:r.querySelector('[name="agingVessel"]').value,duration:r.querySelector('[name="agingDuration"]').value,unit:r.querySelector('[name="agingUnit"]').value})).filter(a=>a.duration);x.aging=x.agingSteps.map(a=>`${a.duration} ${a.unit} ${a.vessel.toLowerCase()==='lieviti'?'sui lieviti':'in '+a.vessel.toLowerCase()}`).join(' · ');x.foodPairings=readRelations(form,'foodPairings');const l=wineLib();const dkey=denomKey(x.country,x.type,x.region),pkey=producerKey(x.country,x.type,x.region,x.denomination);if(x.region){const a=l.regions[x.country]||(l.regions[x.country]=[]);if(!a.includes(x.region))a.push(x.region)}if(x.denomination){const a=l.denominations[dkey]||(l.denominations[dkey]=[]);if(!a.includes(x.denomination))a.push(x.denomination)}if(x.producer){const a=l.producers[pkey]||(l.producers[pkey]=[]);if(!a.includes(x.producer))a.push(x.producer)}saveWineLib(l)}else{const old=x.category;x.category=getVal(form,'category');x.format=getVal(form,'format');x.price=Number(getVal(form,'price'));x.alcohol=['amari','birre','distillati'].includes(x.category)?getVal(form,'alcohol'):'';[...contentLanguages().flatMap(l=>[`name.${l}`,`shortDescription.${l}`,`description.${l}`])].forEach(f=>setPath(x,f,getVal(form,f)));}x.active=$('#field-active').checked;x.image=await imageValue(form,'image');const gallery=[];if(form.elements.galleryEnabled?.checked){for(let i=0;i<3;i++){const v=await imageValue(form,`gallery.${i}`);if(v)gallery.push(v)}}x.images=[x.image,...gallery].filter(Boolean);const newCat=kind==='food'||kind==='drinks'?x.category:x.type;if(isNew){items().filter(p=>(kind==='food'||kind==='drinks'?p.category:p.type)===newCat).forEach(p=>p.order=(p.order||0)+1);x.order=1;items().push(x);newDraft=null}else if(newCat!==oldCat){normalizeCategory(oldCat);items().filter(p=>p!==x&&(kind==='food'||kind==='drinks'?p.category:p.type)===newCat).forEach(p=>p.order=(p.order||0)+1);x.order=1}persist();renderList();scrollAdminTop();await showSaveOverlay({isNew,mode:kind});closeEditor();toast(isNew?'Prodotto creato':'Modifiche salvate')}


function saveOverlayMarkup(mode){
 const fish=`<svg class="save-loader-svg save-loader-fish" viewBox="0 0 180 100" aria-hidden="true"><path class="save-loader-line" d="M20 50 C42 24 84 20 124 48 C139 37 151 31 163 29 C158 41 157 59 163 71 C151 69 139 63 124 52 C84 80 42 76 20 50 Z M52 49 C70 40 91 40 108 49 C91 58 70 58 52 49 Z"/><circle class="save-loader-dot" cx="43" cy="43" r="2.3"/></svg>`;
 const bottle=`<svg class="save-loader-svg save-loader-bottle" viewBox="0 0 110 170" aria-hidden="true"><path class="save-loader-line" d="M43 12 H67 V38 C67 46 73 51 79 57 C85 63 88 72 88 82 V151 C88 157 83 161 77 161 H33 C27 161 22 157 22 151 V82 C22 72 25 63 31 57 C37 51 43 46 43 38 Z M43 26 H67 M29 78 H81"/></svg>`;
 const cocktail=`<svg class="save-loader-svg save-loader-cocktail" viewBox="0 0 140 160" aria-hidden="true"><path class="save-loader-line" d="M20 24 H120 L76 82 V132 H101 M49 132 H101 M64 82 L20 24 M76 82 L120 24 M43 48 H97 M88 39 C101 28 112 29 121 35 C111 43 100 46 88 39 Z"/></svg>`;
 const symbol=mode==='wine'?bottle:mode==='drinks'?cocktail:fish;
 return `<div class="save-overlay" role="status" aria-live="polite"><div class="save-overlay-inner">${symbol}<div class="save-overlay-label">SALVATAGGIO</div></div></div>`;
}
function showSaveOverlay({isNew,mode}){
 const duration=isNew?3000:2000;
 const overlay=document.createElement('div');
 overlay.innerHTML=saveOverlayMarkup(mode);
 const node=overlay.firstElementChild;
 node.style.setProperty('--save-duration',`${duration}ms`);
 node.querySelector('.save-overlay-label').textContent=isNew?(mode==='food'?'CREAZIONE PIATTO':mode==='wine'?'CREAZIONE BOTTIGLIA':'CREAZIONE BEVANDA'):'SALVATAGGIO';
 document.body.appendChild(node);
 requestAnimationFrame(()=>node.classList.add('is-visible'));
 const drawComplete=Math.round(duration*.84);
 const leaveAt=Math.round(duration*.90);
 return new Promise(resolve=>{
  setTimeout(()=>{
   node.classList.add('is-complete');
   node.querySelector('.save-overlay-label').textContent='SALVATO';
  },drawComplete);
  setTimeout(()=>node.classList.add('is-leaving'),leaveAt);
  setTimeout(()=>{node.remove();resolve()},duration);
 });
}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),1800)}
init().catch(err=>{console.error('SCIROCCO ADMIN INIT ERROR:',err);$('#emptyEditor').innerHTML=`<h2>Impossibile caricare i dati</h2><p>${esc(err.message)}</p><p>Apri questa pagina tramite localhost.</p>`});
